import{_ as o,l as E,o as t,c as n,v as d,p as s,x as l,d as r,i as m,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"模型合并：SLERP / TIES / DARE","description":"","frontmatter":{"title":"模型合并：SLERP / TIES / DARE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-merging.md","filePath":"llm/model-merging.md","lastUpdated":1789023840000}'),A={name:"llm/model-merging.md"};function p(S,a,u,c,R,_){const i=E("Mermaid");return t(),n("div",null,[a[1]||(a[1]=d('<h1 id="模型合并-slerp-ties-dare" tabindex="-1">模型合并：SLERP / TIES / DARE <a class="header-anchor" href="#模型合并-slerp-ties-dare" aria-label="Permalink to &quot;模型合并：SLERP / TIES / DARE&quot;">​</a></h1><div class="epigraph"><p>两个微调增量逐元素相加会在符号冲突处互相抵消；先对齐几何、再处理冲突与稀疏，合并才不像在参数空间里掷硬币。</p><footer>—— Shoemake, Animating Rotation with Quaternion Curves, SIGGRAPH 1985（SLERP）；Yadav et al., TIES-Merging, NeurIPS 2023；Yu et al., Language Models are Super Mario (DARE), ICLR 2024</footer></div><p><a href="/llm/dense-to-moe-upcycling">上一课</a>是单检查点变稀疏形状。<a href="/llm/model-soups-averaging">模型汤</a> 是同一盆地里稠密均匀平均。缺口是：<strong>任务不同、增量可能冲突</strong> 的多个微调，如何合成一个权重。SLERP 在球面插值；TIES 处理符号冲突与量级修剪；DARE 随机丢掉增量再缩放。本课写三者的对象都是 \\(\\delta=\\theta_{\\mathrm{ft}}-\\theta_{\\mathrm{base}}\\)，下一课把 \\(\\delta\\) 当成可加减的任务向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀汤假设 \\(\\theta^{(i)}\\) 已在低损失连通集。指令微调 vs 代码微调，路径更长，\\(\\delta\\) 在同一坐标上符号可相反：直接 \\((\\theta_1+\\theta_2)/2\\) 把该坐标抹回基座，两个任务都丢。Yadav 等人的 TIES：修剪小增量、对齐符号（冲突则丢或投票）、再合并。Yu 等人的 DARE：以高概率把 \\(\\delta\\) 的坐标置零，剩余放大 \\(1/(1-p)\\)，发现微调增量极冗余，稀疏后仍能保任务，再与其他 \\(\\delta\\) 相加冲突更少。</p><p>SLERP：对两个权重（或增量）按球面线性插值，而不是欧氏直线。Shoemake 原本为旋转；在高维权重上这是启发式，当 \\(\\|\\theta\\|\\) 接近时与线性插值相近，范数差大时避免欧氏平均缩范数。它不管符号冲突，常作两模型之间的几何，不是多任务冲突的主工具。</p><p><span class="marginnote">合并在 FP32 的 \\(\\delta\\) 上做。基座必须逐比特同一检查点。词表或层数不同，没有逐元素 \\(\\delta\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>统一流程：</p><ol><li>固定基座 \\(\\theta_0\\)，算 \\(\\delta_i=\\theta_i-\\theta_0\\)。</li><li><strong>可选 DARE：</strong> 独立 Bernoulli 保留，再 rescale。</li><li><strong>可选 TIES：</strong> 按幅值修剪；符号冲突决议（多数或丢弃）。</li><li>求和或加权求和 \\(\\delta\\)，加回 \\(\\theta_0\\)。</li><li>两模型、无冲突需求时，可用 SLERP\\((\\theta_a,\\theta_b;\\lambda)\\) 代替欧氏。</li></ol><p>与汤的选择：同一任务多样超参 → 汤或 EMA；多任务增量 → TIES/DARE。不要对已经汤过的权重再当 \\(\\delta\\) 用不同基座减——基座要对齐。</p><p>验收：各源任务的验证集；合并后若一任务崩、另一任务满血，是冲突决议吃掉了前者的符号。调修剪率而不是再加学习率去「修」合并模型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微调增量冗余（DARE 的经验）：很多坐标的 \\(\\delta\\) 对损失不敏感，丢掉它们减少与其他任务冲突的表面积。TIES 的符号对齐承认：冲突坐标没有线性好解，与其平均成 0，不如选一侧或置零。SLERP 保范数，避免欧氏平均把两个同方向大向量收成更短的向量从而改变有效学习后的尺度——这与激活尺度课同类，只是发生在权重范数上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合并不是训练，没有 \\(m,v\\)。合并后若再微调，优化器状态应从 0 起。许可与安全：合并会混合各源的行为，包括拒绝策略，本课只写数值。下一课把 \\(\\delta\\) 显式命名为任务向量，做加减算术。</p>',16)),(t(),s(h,null,{default:l(()=>[m(i,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%90%8C%E4%B8%80%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20D%5B%22%E5%A2%9E%E9%87%8F%20delta%22%5D%0A%20%20D%20--%3E%20DARE%5B%22%E5%8F%AF%E9%80%89%E7%A8%80%E7%96%8F%20rescale%22%5D%0A%20%20DARE%20--%3E%20TIES%5B%22%E4%BF%AE%E5%89%AA%E4%B8%8E%E7%AC%A6%E5%8F%B7%E5%86%B3%E8%AE%AE%22%5D%0A%20%20TIES%20--%3E%20ADD%5B%22%E5%8A%A0%E5%9B%9E%E5%9F%BA%E5%BA%A7%22%5D%0A%20%20B%20--%3E%20SL%5B%22%E4%B8%A4%E6%A8%A1%E5%9E%8B%20SLERP%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"多任务增量用 \\(\\delta\\) 空间；汤用同一盆地的稠密平均。"),e("li",null,"DARE 利用增量冗余降冲突表面积；TIES 处理符号；SLERP 是两模型球面插值。"),e("li",null,"基座与精度必须对齐；崩了调修剪/决议，不要当新模型去猛训掩盖。"),e("li",null,"合并后无 Adam 状态，再训从 0 计。"),e("li",null,"出处：Shoemake, SIGGRAPH 1985；Yadav et al., NeurIPS 2023；Yu et al., ICLR 2024。")],-1))])}const P=o(A,[["render",p]]);export{D as __pageData,P as default};
